                                (Some(_), _) => other_parts = other_parts.saturating_add(1),
                                (None, _) => return fallback,
                            }
                        }
                    }
                    content => {
                        if !add_text(content, &mut text_bytes) {
                            return fallback;
                        }
                    }
                }
            }
        }
        input => {
            if !add_text(input, &mut text_bytes) {
                return fallback;
            }
        }
    }
