                    }
                }
                match item.get("output") {
                    None | Some(Value::Null) => {}
                    Some(Value::String(text)) => text_bytes = text_bytes.saturating_add(text.len()),
                    Some(other) => text_bytes = text_bytes.saturating_add(json_len(other)),
                }
